import { z } from 'zod';
import pins from './pins.json';

/**
 * The add-on versions this build needs, generated by `scripts/build-addons.mjs`
 * from each add-on's own `addon.json` (and, for the Copilot CLI, from the
 * `@github/copilot` package version).
 *
 * The application names the exact version and API version it was built against:
 * a published catalogue may hold many versions at once, and an installed add-on
 * of another version is never used - the pinned one is downloaded and the older
 * one deleted.
 */

export const addonPinsSchema = z.record(
  z.string().regex(/^[a-z][a-z0-9-]{0,63}$/),
  z
    .object({
      version: z.string().regex(/^\d+\.\d+\.\d+$/),
      apiVersion: z.number().int().positive(),
    })
    .strict(),
);

export type AddonPins = z.infer<typeof addonPinsSchema>;

export interface AddonPin {
  readonly version: string;
  readonly apiVersion: number;
}

/**
 * The pins this build ships. Parsed once, at module load: a malformed generated
 * file is a build fault and must fail loudly rather than silently install
 * nothing.
 */
export const addonPins: AddonPins = addonPinsSchema.parse(pins);

export function pinFor(id: string): AddonPin | undefined {
  return addonPins[id];
}
